import{$,api,escapeHtml,fillFilters,queryString,renderMarkdown,showError,wirePager}from"./common.js";let currentPage=1;async function load(page=1){currentPage=page;try{const data=await api(`/api/learning?${queryString(page,8)}`);$("#result").textContent=`共 ${data.total.toLocaleString()} 篇文档`;$("#list").innerHTML=data.items.length?data.items.map((item)=>`<article class="card"><h2>${escapeHtml(item.title)}</h2><div class="source-line">${escapeHtml(item.repository)} · ${escapeHtml(item.module)} · ${escapeHtml(item.relative_path)}</div><details class="answer"><summary>展开知识原文</summary><div class="markdown">${renderMarkdown(item.markdown)}</div><p><a target="_blank" rel="noopener" href="${item.repository_url}/blob/HEAD/${encodeURI(item.relative_path)}">查看仓库原文件 ↗</a></p></details></article>`).join(""):'<div class="empty">没有符合条件的文档</div>';wirePager({page:data.page,pages:data.pages,onChange:load})}catch(error){showError(error)}}await fillFilters();for(const id of["q","module","source"]){$("#"+id).addEventListener(id==="q"?"input":"change",()=>load(1))}await load();
